from author_tools import *
N(bank,7,231,A,'Прямая и обратная пропорциональность в моделях','41',[
('7-proportion-direct-k','Зависимость y прямо пропорциональна x. При x = 4 известно y = 18. Найдите коэффициент пропорциональности.',4.5,'В y = kx коэффициент k = y/x = 18/4 = 4,5.','F(18,4)','b'),
('7-proportion-inverse-k','В обратной пропорциональности y = k/x при x = 6 имеем y = 5. Найдите k.',30,'Произведение x и y постоянно: k = 6 · 5 = 30.','6*5','b'),
('7-proportion-direct-signed','y прямо пропорционально x, причём при x = −3 известно y = 12. Найдите y при x = 5.',-20,'Коэффициент 12/(−3) = −4. При x = 5 значение −20.','12/(-3)*5','m'),
('7-proportion-inverse-change','Величины x и y обратно пропорциональны и положительны. x увеличили на 25%. На сколько процентов уменьшилось y?',20,'x стало 5/4 прежнего, значит y стало 4/5 прежнего. Уменьшение 1/5 = 20%.','(1-1/F(125,100))*100','h'),
('7-proportion-table-detection','Даны пары (x;y): (2;18), (3;12), (6;6). Если зависимость является прямой или обратной пропорциональностью, найдите её постоянную величину k.',36,'Произведения x · y равны 36, а частные различны. Это обратная пропорциональность с k = 36.','next(iter({x*y for x,y in [(2,18),(3,12),(6,6)]}))','m'),
('7-proportion-fixed-price-budget','При постоянной сумме покупки количество товара обратно пропорционально цене. Цена снизилась с 80 до 64 рублей. Во сколько раз можно увеличить количество?',1.25,'Отношение количеств равно обратному отношению цен: 80/64 = 1,25.','F(80,64)','m'),
('7-proportion-joint-two-inputs','Объём продукции прямо пропорционален числу станков и времени работы. 3 станка за 4 часа делают 240 деталей. Сколько деталей сделают 5 станков за 6 часов?',600,'Один станок за час делает 240/(3 · 4) = 20 деталей. За 30 станко-часов получится 600.','240/(3*4)*5*6','h'),
('7-proportion-nonproportional-fee','Стоимость y равна 200 + 30x при x > 0. Найдите разность y(2)/2 − y(4)/4.',50,'y(2)/2 = 130, y(4)/4 = 80. Разность 50; наличие постоянной платы нарушает прямую пропорциональность.','(200+30*2)/2-(200+30*4)/4','h'),
('7-proportion-intersect-direct-inverse','Графики y = 3x и y = 12/x пересекаются. Найдите сумму ординат всех точек пересечения.',0,'Имеем 3x² = 12, x = ±2. Ординаты ±6, их сумма 0.','sum(3*x for x in qroots(3,0,-12))','h'),
('7-proportion-negative-product-sign','При y = −24/x найдите сумму значений y для x = −2 и x = 3.',4,'Получаем y(−2) = 12, y(3) = −8. Сумма 4.','F(-24,-2)+F(-24,3)','m'),
('7-proportion-integer-lattice-count','Сколько точек с положительными целыми координатами лежит на графике y = 36/x?',9,'x должен быть положительным делителем 36. Это 1,2,3,4,6,9,12,18,36 — девять точек.','sum(36%x==0 for x in range(1,37))','s'),
('7-proportion-fixed-sum-product','Положительные величины связаны x + y = 10 и y = 16/x. Найдите сумму всех возможных значений x.',10,'Из xy = 16 и суммы 10 получаем пары 2 и 8. Возможные x равны 2 и 8, сумма 10.','sum(x for x in range(1,10) if x*(10-x)==16)','s')])
N(bank,7,232,A,'Текстовые модели: проценты, смеси и концентрации','41–42',[
('7-mixture-salt-mass','В 350 г раствора 8% соли. Сколько граммов соли в растворе?',28,'Масса соли 350 · 0,08 = 28 г.','350*F(8,100)','b'),
('7-mixture-two-metals-ratio','Сплав содержит 12 г меди и 28 г цинка. Найдите процент меди в сплаве.',30,'Масса сплава 40 г. Доля меди 12/40 = 30%.','12/(12+28)*100','b'),
('7-mixture-add-pure-solute','К 200 г раствора с 10% соли добавили 25 г соли. Каков процент соли в новом растворе?',20,'Соли стало 20 + 25 = 45 г, общая масса 225 г. Содержание 20%.','(200*F(10,100)+25)/(200+25)*100','m'),
('7-mixture-remove-solution','Из 500 г 12%-го раствора отлили 200 г. Каков процент соли в оставшемся растворе, если раствор однородный?',12,'При отливании однородного раствора соль и вода убывают в одинаковой пропорции. Концентрация остаётся 12%.','((500-200)*F(12,100))/(500-200)*100','m',{'tricky':True}),
('7-mixture-replace-water','Из 300 г 20%-го раствора отлили 100 г и добавили 100 г воды. Каков процент соли в результате?',(40/3,'40/3'),'После отливания в 200 г остаётся 40 г соли. Масса снова 300 г, концентрация 40/300 · 100% = 40/3%.','((300-100)*F(20,100))/300*100','h'),
('7-mixture-unknown-mass-one','К 100 г 10%-го раствора добавили 30%-й раствор. Получили 20%-й раствор. Сколько граммов второго раствора добавили?',100,'Равные отклонения 10 процентных пунктов означают равные массы. Можно записать 10 + 0,3x = 0,2(100 + x), откуда x = 100.','(100*F(20,100)-100*F(10,100))/(F(30,100)-F(20,100))','h'),
('7-percent-percentage-points','Доля успеха выросла с 40% до 50%. На сколько процентов выросло само число процентов относительно исходного?',25,'Прибавка 10 процентных пунктов составляет 10/40 = 25% исходной доли.','(50-40)/40*100','m'),
('7-percent-profit-cost','Товар продали за 720 рублей с прибылью 20% от себестоимости. Найдите прибыль в рублях.',120,'Себестоимость 720/1,2 = 600 рублей. Прибыль 720 − 600 = 120 рублей.','720-720/F(120,100)','m'),
('7-percent-ratio-mixture','Два раствора содержат 5% и 25% вещества. В каком отношении массы первого ко второму нужно смешать, чтобы получить 20%-й раствор? Введите это отношение как число.',(1/3,'1/3'),'Прибавка второго относительно 20% равна 5 пунктам, недостаток первого 15. Для баланса масса первого составляет 5/15 = 1/3 массы второго.','F(25-20,20-5)','h'),
('7-percent-price-fixed-revenue','После снижения цены на 20% количество продаж выросло на 25%. На сколько процентов изменилась выручка? Рост считайте положительным.',0,'Выручка умножилась на 0,8 · 1,25 = 1. Изменение 0%.','(F(80,100)*F(125,100)-1)*100','h'),
('7-mixture-dry-matter','Свежие грибы содержат 90% воды, сушёные — 20%. Из 8 кг свежих получили сушёные без потери сухого вещества. Сколько килограммов сушёных получилось?',1,'Сухого вещества 0,8 кг. В сушёных оно составляет 80%, значит масса 0,8/0,8 = 1 кг.','8*(1-F(90,100))/(1-F(20,100))','s'),
('7-mixture-two-replacements','Из 100 л 20%-го раствора дважды отливали по 50 л и каждый раз восполняли объём чистой водой. Сколько литров вещества осталось?',5,'При каждой замене удаляется половина вещества. Из 20 л после двух замен остаётся 20 · 1/2 · 1/2 = 5 л.','100*F(20,100)*(1-F(50,100))**2','s')])
N(bank,7,233,A,'Уравнения с параметром и равносильность','42',[
('7-param-root-zero','При каком a число x = 0 является корнем уравнения 5x + a = 12?',12,'Подставляем x = 0. Получаем a = 12.','12-5*0','b'),
('7-param-linear-one-root-value','При a = −2 решите уравнение (a + 3)x = 7.',7,'Коэффициент a + 3 равен 1, поэтому x = 7.','7/(-2+3)','b'),
('7-param-zero-coefficient-identity','При a = 4 уравнение (a − 4)x = 2a − 8 выполняется для всех x. Сколько его целых корней между −5 и 5 включительно?',11,'Обе части равны нулю. Подходят все 11 целых чисел указанного промежутка.','sum((4-4)*x==2*4-8 for x in range(-5,6))','m'),
('7-param-one-root-universal','Для всех a уравнение 3x + a = a − 9 имеет один и тот же корень. Найдите его.',-3,'Параметр сокращается: 3x = −9, поэтому x = −3.','-9/3','m'),
('7-param-roots-opposite','Уравнения 2x + a = 7 и 3x − 2a = 4 имеют противоположные корни. Найдите a.',-29,'Корни (7 − a)/2 и (4 + 2a)/3. Их сумма 0 даёт 21 − 3a + 8 + 4a = 0, поэтому a = −29.','-(3*7+2*4)/(2*2-3)','h'),
('7-param-equivalent-scale','Уравнения 4x − 8 = 0 и ax − 12 = 0 равносильны. Найдите a.',6,'Первое имеет единственный корень 2. Подставляем во второе: 2a − 12 = 0, a = 6.','12/(8/4)','m'),
('7-param-multiply-zero-loses','Уравнение x = 3 умножили на x − 1 и получили (x − 3)(x − 1) = 0. Какой лишний корень появился?',1,'Новое уравнение выполняется и при x − 1 = 0. Значение 1 не удовлетворяет исходному x = 3.','next(x for x in qroots(1,-4,3) if x!=3)','h',{'tricky':True}),
('7-param-add-root-condition','Корень уравнения ax − 6 = 0 равен сумме 1 и 2. Найдите a.',2,'Указанный корень 3. Из 3a = 6 следует a = 2.','6/(1+2)','m'),
('7-param-no-solution-one-value','При каком a уравнение (2a − 6)x = a + 1 не имеет решений?',3,'Ненулевой коэффициент даёт корень. При a = 3 коэффициент нулевой, а правая часть 4 ненулевая; решений нет.','next(a for a in range(-10,11) if 2*a-6==0 and a+1!=0)','h'),
('7-param-forbidden-division','В уравнении (x − 2)(x + 5) = 0 разделили обе части на x − 2. Какой корень потеряли?',2,'Деление недопустимо при x = 2. Именно этот корень исчез; после деления остался только x = −5.','next(x for x in qroots(1,3,-10) if x-2==0)','h',{'tricky':True}),
('7-param-product-constant-count','Сколько целых a от −3 до 3 делают уравнение ax = a имеющим ровно один корень?',6,'При a ≠ 0 корень x = 1 единственный. При a = 0 подходит любое x. Из семи значений исключаем ноль, остаётся шесть.','sum(a!=0 for a in range(-3,4))','s'),
('7-param-root-fixed-under-change','Найдите общий корень всех уравнений (a + 2)x = 3a + 6, где a — любое действительное число, кроме −2.',3,'Правая часть 3(a + 2). При a ≠ −2 можно разделить на a + 2 и получить x = 3.','(3*5+6)/(5+2)','s')])
N(bank,7,234,A,'Многочлены: значения, симметрия и целочисленность','42',[
('7-poly-zero-constant-read','Для P(x) = 8x⁴ − 3x + 6 найдите P(0).',6,'При x = 0 все члены с переменной обращаются в ноль. Остаётся 6.','8*0**4-3*0+6','b'),
('7-poly-even-function-diff','Для P(x) = 2x⁴ + 3x² − 1 найдите P(−2) − P(2).',0,'В многочлене только чётные степени, поэтому значения при противоположных аргументах равны.','(2*(-2)**4+3*(-2)**2-1)-(2*2**4+3*2**2-1)','b'),
('7-poly-odd-function-sum','Для P(x) = x⁵ − 7x³ + 2x найдите P(3) + P(−3).',0,'Каждая степень нечётна, поэтому P(−3) = −P(3). Сумма 0.','(3**5-7*3**3+2*3)+((-3)**5-7*(-3)**3+2*(-3))','m'),
('7-poly-from-known-expression','Известно x² − 2x = 9. Найдите 3x² − 6x + 4.',31,'Группируем 3(x² − 2x) + 4 = 27 + 4 = 31.','3*9+4','m'),
('7-poly-shift-value','Пусть P(x) = x² − x. Найдите P(x + 1) − P(x) при x = 7.',14,'Разность (x + 1)² − (x + 1) − x² + x упрощается до 2x. При x = 7 она равна 14.','((7+1)**2-(7+1))-(7**2-7)','m'),
('7-poly-even-integer-product','Для скольких целых n от 1 до 20 число n² + n нечётно?',0,'n² + n = n(n + 1), произведение двух соседних целых всегда чётно. Поэтому ни для одного.','sum((n*n+n)%2==1 for n in range(1,21))','h'),
('7-poly-divisibility-six','Найдите остаток от деления 13³ − 13 на 6.',0,'Разложение 13(13 − 1)(13 + 1) — произведение трёх последовательных чисел. Оно делится и на 2, и на 3. Остаток 0.','(13**3-13)%6','h'),
('7-poly-fixed-square-neighbor','Два последовательных натуральных числа имеют квадраты, разность которых 25. Найдите большее число.',13,'Если меньшее n, разность (n + 1)² − n² = 2n + 1. Из 2n + 1 = 25 получаем n = 12, большее 13.','(25+1)/2','m'),
('7-poly-parameter-symmetry','Многочлен P(x) = x² + ax + 5 удовлетворяет P(2) = P(−2). Найдите a.',0,'Разность значений равна 4a. Из 4a = 0 следует a = 0.','next(a for a in range(-10,11) if 2**2+a*2+5==(-2)**2+a*(-2)+5)','h'),
('7-poly-telescope-square-difference','Найдите сумму (2² − 1²) + (3² − 2²) + … + (10² − 9²).',99,'Промежуточные квадраты попарно сокращаются. Остаётся 10² − 1² = 99.','sum(k*k-(k-1)*(k-1) for k in range(2,11))','h'),
('7-poly-product-square-offset','Найдите наименьшее значение (x − 1)(x − 3) при действительных x.',-1,'Произведение равно x² − 4x + 3 = (x − 2)² − 1. Минимум −1 достигается при x = 2.','3-(-4)**2/4','s'),
('7-poly-divisor-argument','Найдите сумму всех натуральных n, для которых число n² + 3n + 2 делится на n.',3,'n² и 3n уже делятся на n. Значит n должен делить 2, возможны 1 и 2. Их сумма 3.','sum(n for n in range(1,100) if (n*n+3*n+2)%n==0)','s')])
N(bank,7,235,A,'Графики и геометрические данные','42',[
('7-graph-point-on-line','Точка (a; 5) лежит на прямой y = 2x − 1. Найдите a.',3,'Подставляем y = 5: 5 = 2a − 1. Значит a = 3.','(5+1)/2','b'),
('7-graph-on-both-axes','График y = −5x проходит через начало координат. Найдите расстояние от начала координат до точки графика с x = 0.',0,'При x = 0 получаем y = 0. Это само начало координат, расстояние ноль.','abs(-5*0)','b'),
('7-graph-horizontal-segment','Точки A(−1; 4), B(6; 4) принадлежат графику линейной функции. Найдите её значение при x = 100.',4,'Через две точки с одинаковой ординатой проходит горизонтальная прямая y = 4.','4+(4-4)/(6-(-1))*(100-(-1))','m'),
('7-graph-intercept-triangle-area','Прямая y = −2x + 6 пересекает оси в A и B. Найдите площадь прямоугольного треугольника OAB.',9,'Пересечения: (3;0) и (0;6). Площадь половины прямоугольника 3 × 6 равна 9.','(-6/(-2))*6/2','m'),
('7-graph-through-diagonal-square','Прямая через (0; 0) и (4; 4) пересекает вертикаль x = −3. Найдите ординату точки пересечения.',-3,'Её формула y = x, поскольку наклон 1 и свободный член 0. При x = −3 значение −3.','(4-0)/(4-0)*(-3)','m'),
('7-graph-symmetric-line-yaxis','Прямую y = 3x − 2 отразили относительно оси ординат. Найдите коэффициент при x у полученной прямой.',-3,'При отражении x заменяется на −x. Получается y = −3x − 2, коэффициент −3.','3*(-1)','h'),
('7-graph-symmetric-line-origin','Прямую y = 2x + 7 отразили относительно начала координат. Найдите ординату её пересечения с осью y.',-7,'Обе координаты меняют знак. Новая формула y = 2x − 7, пересечение имеет ординату −7.','-(2*0+7)','h'),
('7-graph-square-vertex-param','График y = kx + 1 проходит через правую верхнюю вершину квадрата с вершинами (0;0),(4;0),(4;4),(0;4). Найдите k.',.75,'Условие точки (4;4) даёт 4 = 4k + 1. Поэтому k = 3/4.','F(4-1,4)','m'),
('7-graph-two-intercepts-sum','График y = kx + 12 пересекает положительную полуось x в точке с абсциссой 3. Найдите значение функции при x = 5.',-8,'Из 0 = 3k + 12 получаем k = −4. При x = 5: −20 + 12 = −8.','(-12/3)*5+12','h'),
('7-graph-crossing-diagonal-intercept','Прямая y = 2x + b пересекает y = x в точке с ординатой −4. Найдите b.',4,'На y = x обе координаты равны −4. Подставляем: −4 = −8 + b, значит b = 4.','-4-2*(-4)','h'),
('7-graph-family-fixed-point','Все прямые y = a(x − 3) + 2 при разных действительных a проходят через одну точку. Найдите сумму её координат.',5,'Чтобы значение не зависело от a, нужно x − 3 = 0. Тогда x = 3, y = 2, сумма 5.','3+2','s'),
('7-graph-equal-intercepts-square','Прямая y = kx + 8 пересекает положительные полуоси в точках, равноудалённых от начала координат. Найдите k.',-1,'Вертикальный отрезок до пересечения равен 8. Горизонтальный тоже 8, значит 0 = 8k + 8 и k = −1.','-8/8','s')])
N(bank,7,236,P,'Восстановление данных по статистическим характеристикам','92',[
('7-stat-total-two-values','В наборе четыре тройки и две девятки. Найдите сумму всех наблюдений.',30,'Сумма 4 · 3 + 2 · 9 = 30.','4*3+2*9','b'),
('7-stat-maximum-from-range-min','Минимум набора равен −5, размах 17. Найдите максимум.',12,'Максимум равен минимуму плюс размах: −5 + 17 = 12.','-5+17','b'),
('7-stat-multiplicity-mean','В наборе только числа 2 и 8, всего 10 наблюдений. Среднее равно 5. Сколько в наборе восьмёрок?',5,'Если восьмёрок k, сумма 8k + 2(10 − k) = 50. Получаем 6k = 30, k = 5.','(10*5-10*2)/(8-2)','m'),
('7-stat-frequency-table-mean','В таблице число 1 имеет частоту 2, число 3 — частоту 4, число 5 — частоту 2. Найдите среднее.',3,'Сумма наблюдений 2 + 12 + 10 = 24, их восемь. Среднее 3.','(1*2+3*4+5*2)/(2+4+2)','m'),
('7-stat-even-median-unknown','Четыре числа по порядку: 2, x, 8, 15. Их медиана 6. Найдите x.',4,'Медиана равна (x + 8)/2. Из равенства 6 получаем x = 4.','2*6-8','m'),
('7-stat-sum-range-extremes','Пять чисел имеют сумму 40. После удаления минимума и максимума среднее оставшихся равно 7, размах исходного набора 9. Найдите максимум.',14,'Сумма крайних 40 − 21 = 19, разность 9. Максимум (19 + 9)/2 = 14.','(40-3*7+9)/2','h'),
('7-stat-median-after-delete','В наборе 1,2,3,4,5,6,7 удалили одно число. Медиана оставшегося набора 4,5. Найдите сумму всех возможных удалённых чисел.',6,'Чтобы два средних были 4 и 5, нужно удалить 1, 2 или 3. Их сумма 6.','sum(v for v in range(1,8) if median([n for n in range(1,8) if n!=v])==F(9,2))','h'),
('7-stat-two-groups-count','В одной группе среднее 6, в другой 9. Общее среднее 8. Если в первой 12 наблюдений, сколько во второй?',24,'Отклонение первой группы от 8 равно 2, второй 1. Для баланса во второй должно быть вдвое больше наблюдений, то есть 24.','12*(8-6)/(9-8)','h'),
('7-stat-mean-integer-feasibility','Можно ли получить среднее 3,25 у пяти целых чисел? Введите 1, если да, и 0, если нет.',0,'Требуемая сумма 5 · 3,25 = 16,25 не целая. Сумма целых чисел целая, поэтому невозможно.','int((5*F("3.25")).denominator==1)','h'),
('7-stat-append-median-unchanged','К набору 2,4,6,8 добавили число x. Медиана стала 6. Найдите наименьшее целое x, при котором это возможно.',6,'До добавления перед 6 стоят 2 и 4. Чтобы 6 оказалось третьим, добавленное число должно быть не меньше 6. Минимум 6.','min(x for x in range(-10,20) if median([2,4,6,8,x])==6)','m'),
('7-stat-distinct-integer-minrange','Пять различных целых чисел имеют среднее 10. Найдите наименьший возможный размах.',4,'Различные целые занимают не менее пяти подряд идущих позиций, размах не меньше 4. Набор 8,9,10,11,12 имеет нужное среднее и размах 4.','min(max(v)-min(v) for v in combinations(range(6,15),5) if sum(v)==50)','s'),
('7-stat-mean-median-constrain-largest','Три неотрицательных целых числа имеют среднее 4 и медиану 3. Сколько различных значений может иметь их размах?',4,'Пусть числа a ≤ 3 ≤ c, a + c = 9. a может быть 0,1,2,3, тогда размахи 9,7,5,3 — четыре значения.','len({c-a for a in range(4) for c in range(3,13) if a+3+c==12})','s')])
N(bank,7,237,G,'Геометрические конфигурации: выбор дополнительной связи','71',[
('7-config-midpoint-equal-radii','M — середина диаметра AB окружности, AB = 18 см. Точка C на окружности. Найдите MC.',9,'Середина диаметра — центр окружности. MC — радиус, равный 9 см.','18/2','b'),
('7-config-median-base-unknown','В равнобедренном ABC медиана AM проведена к основанию BC. BM = 4,5 см. Найдите BC.',9,'M — середина BC. Поэтому BC = 2BM = 9 см.','2*F("4.5")','b'),
('7-config-height-equal-side','В равнобедренном ABC равны AB и BC, высота BH опущена на AC. Угол ABH = 19°. Найдите угол ABC.',38,'Высота из вершины равнобедренного треугольника является биссектрисой. Вершинный угол 38°.','2*19','m'),
('7-config-external-isosceles-split','В ABC AB = AC, внешний угол при вершине A равен 130°. Найдите угол между высотой из A и стороной AB.',25,'Внутренний угол A равен 50°. Высота его делит пополам, угол 25°.','(180-130)/2','m'),
('7-config-center-tangent-thirty','Из P проведена касательная PA к окружности центра O. Угол APO = 30°, OP = 16 см. Найдите радиус OA.',8,'Радиус к точке касания перпендикулярен PA. В прямоугольном OAP радиус лежит против 30°, значит равен половине OP: 8 см.','16/2','h'),
('7-config-circumcenter-right-location','В прямоугольном ABC гипотенуза AB = 26 см. O — центр описанной окружности. Найдите OC.',13,'Центр описанной окружности прямоугольного треугольника — середина гипотенузы. Радиус равен 13 см.','26/2','m'),
('7-config-bisector-perpendicular-equal','В ABC биссектриса AM одновременно перпендикулярна BC. AB = 2x + 5, AC = 4x − 3 см. Найдите AB.',13,'Прямоугольные ABM и ACM равны по катету AM и острому углу. Поэтому AB = AC, x = 4, AB = 13.','2*((5+3)/(4-2))+5','h'),
('7-config-equal-distance-two-base','Точки P и Q равноудалены от A и B. P ≠ Q. Прямая PQ пересекает AB в M. AB = 14 см. Найдите AM.',7,'P и Q лежат на серединном перпендикуляре к AB, значит PQ — эта прямая. M является серединой AB, AM = 7 см.','14/2','h'),
('7-config-acute-largest-side','В ABC угол A = 45°, B = 60°. Какой номер стороны самой длинной: 1 для AB, 2 для BC, 3 для AC?',1,'Угол C = 75° наибольший. Против него лежит AB, это сторона номер 1.','[1,2,3][[180-45-60,45,60].index(max([180-45-60,45,60]))]','m'),
('7-config-isosceles-triangle-ring','В треугольнике ABC AB = BC. Внешний угол при A равен удвоенному внутреннему углу B. Найдите B.',60,'Пусть A = C = x, B = 180 − 2x. По условию 180 − x = 2(180 − 2x). x = 60, значит B = 60.','180-2*((360-180)/(4-1))','h'),
('7-config-internal-external-bisector','В треугольнике ABC угол A = 50°. Внутренняя биссектриса B и внешняя биссектриса C пересекаются в P. Найдите меньший угол между прямыми BP и CP.',25,'Угол между внутренними биссектрисами B и C равен 115°. Внешняя биссектриса C перпендикулярна внутренней, меньший угол равен 115 − 90 = 25°.','(90+50/2)-90','s'),
('7-config-equilateral-two-midpoint','В равностороннем ABC точки M и N — середины AB и AC. Периметры треугольников ABC и AMN в сумме равны 54 см. Найдите AB.',12,'По равным половинам сторон и углу 60° треугольник AMN равносторонний со стороной AB/2. Периметры дают 3a + 1,5a = 54, a = 12 см.','54/(3+F(3,2))','s')])
N(bank,7,238,P,'Графы как модель ограничений и маршрутов','92–93',[
('7-graph-handshake-degree-person','На встрече Петя пожал руки Ане, Боре и Вере. Другие рукопожатия не описаны. Найдите степень Пети в графе рукопожатий.',3,'У вершины Пети три ребра к названным участникам. Степень 3.','len(["Аня","Боря","Вера"])','b'),
('7-graph-road-adjacency','Дороги есть между A и B, A и C, C и D. Сколько городов соседствуют непосредственно с C?',2,'У C соседи A и D. Город B связан только через A и непосредственным соседом C не является.','g67_degrees("ABCD",["AB","AC","CD"])["C"]','b'),
('7-graph-round-robin-missing','Пять команд должны сыграть каждая с каждой один раз. Уже сыграно 7 матчей. Сколько осталось?',3,'Всего 10 пар команд. После 7 игр остаётся 3 матча.','len(list(combinations(range(5),2)))-7','m'),
('7-graph-avoid-closed-road','Есть дороги AB, BC, CD, DA и AC, каждая длиной 1 км. AC закрыли. Найдите кратчайший путь из A в C в километрах.',2,'Остаются пути через B или через D, оба по 2 км.','g67_shortest("ABCD",["AB","BC","CD","DA"],"A","C")','m'),
('7-graph-color-cycle-odd','По кругу стоят пять домов, соседние должны иметь разные цвета. Каково наименьшее число цветов?',3,'Двух цветов не хватит: при чередовании первый и пятый совпадут. Трёх достаточно, например 1,2,1,2,3.','min(k for k in range(1,6) if any(all(cs[i]!=cs[(i+1)%5] for i in range(5)) for cs in product(range(k),repeat=5)))','h'),
('7-graph-acquaintance-universal','В компании 5 человек каждый знаком со всеми остальными. Одна пара поссорилась, и знакомство между ними удалили из графа. Сколько человек осталось знакомо со всеми остальными?',3,'Только два конца удалённого ребра потеряли по одному знакомству. Остальные три по-прежнему знакомы со всеми.','sum(d==4 for d in g67_degrees(range(5),[e for e in combinations(range(5),2) if e!=(0,1)]).values())','h'),
('7-graph-directed-paths-branch','Даны дуги A→B, A→C, B→D, C→D, D→E. Сколько направленных путей из A в E?',2,'Можно выбрать начало через B или через C, далее оба пути идут D→E. Всего два.','len(g67_paths("ABCDE",["AB","AC","BD","CD","DE"],"A","E",True))','m'),
('7-graph-transit-transfer-min','Маршруты метро представлены цепями A–B–C и D–B–E–F. Сколько перегонов в кратчайшем пути от A до F?',3,'Нужно A–B–E–F. Это три ребра графа.','g67_shortest("ABCDEF",["AB","BC","DB","BE","EF"],"A","F")','m'),
('7-graph-all-even-degree-complement','В простом графе на 6 вершинах степень каждой равна 3. Все отсутствующие рёбра добавили, а прежние удалили. Найдите степень каждой вершины нового графа.',2,'У каждой вершины пять возможных соседей. Из них три были соседями, два не были. В новом графе степень 2.','(6-1)-3','h'),
('7-graph-paths-with-midpoint','Рёбра графа: AB, AC, BC, BD, CD. Сколько простых путей A–D проходят через B?',3,'Это A–B–D, A–B–C–D и A–C–B–D. Путь A–C–D через B не проходит.','sum("B" in p for p in g67_paths("ABCD",["AB","AC","BC","BD","CD"],"A","D"))','h'),
('7-graph-four-odd-min-traversal','Граф — квадрат ABCD со сторонами по 1 км и диагональю AC длиной 2 км. Нужно пройти все рёбра и вернуться в A. Найдите наименьшую длину маршрута.',8,'Длина всех рёбер 6 км. Нечётны только A и C, поэтому требуется дополнительно связать их повторным путём длиной 2 км. Минимум 8 км.','4+2+g67_shortest("ABCD",[("A","B",1),("B","C",1),("C","D",1),("D","A",1),("A","C",2)],"A","C")','s'),
('7-graph-schedule-conflicts-three','Четыре кружка A,B,C,D нужно поставить по временным слотам. Общие участники есть у пар AB, BC, CA и CD; такие пары нельзя ставить одновременно. Каково наименьшее число слотов?',3,'Кружки A,B,C попарно конфликтуют, нужны три слота. D можно поставить одновременно с A или B, поэтому трёх достаточно.','min(k for k in range(1,5) if any(all(cs["ABCD".index(a)]!=cs["ABCD".index(b)] for a,b in ["AB","BC","CA","CD"]) for cs in product(range(k),repeat=4)))','s')])
